type Result<T> =
  | { kind: 'ok'; value: T }
  | { kind: 'err'; error: Error };

function render<T>(r: Result<T>): string {
  switch (r.kind) {
    case 'ok':
      return String(r.value);
    case 'err':
      return r.error.message;
    default: {
      const unreachable: never = r;
      // Adding a third kind makes this line fail to compile,
      // pointing at the switch that needs updating.
      return JSON.stringify(unreachable);
    }
  }
}

